<?php
use App\Models\{Testimonial,User}; use Illuminate\Foundation\Testing\RefreshDatabase; uses(RefreshDatabase::class); beforeEach(function(){file_put_contents(storage_path('app/installed'),now()->toIso8601String());App\Models\WebsiteSetting::query()->create(['site_name'=>'Test','site_url'=>'https://example.test','timezone'=>'UTC']);}); afterEach(fn()=>@unlink(storage_path('app/installed'))); test('testimonial listing only exposes visible records',function(){Testimonial::factory()->create(['person_name'=>'Private Person']);Testimonial::factory()->published()->create(['person_name'=>'Public Person','rating'=>null]);$this->get('/testimonials')->assertSuccessful()->assertSee('Public Person')->assertDontSee('Private Person')->assertDontSee('Rating:');}); test('testimonial validation rejects false shapes and unsafe content',function(){$user=User::factory()->create(['is_active'=>true]);$this->actingAs($user)->post('/content/testimonials',['person_name'=>'','quote'=>'','rating'=>6,'image_path'=>'logo.svg','source_url'=>'javascript:alert(1)'])->assertSessionHasErrors(['person_name','quote','rating','image_path','source_url']);}); test('testimonial admin is protected',function(){$this->get('/content/testimonials')->assertRedirect('/login');});
